1	import { useRef, useCallback, useEffect } from 'react';
2	
3	// Variações de tom para cada contexto
4	const TONES = {
5	  pedido:     [[523, 0, 0.12], [659, 0.15, 0.12], [784, 0.3, 0.12], [1047, 0.45, 0.3]],  // C5 E5 G5 C6 — novo pedido (restaurante)
6	  cozinha:    [[784, 0, 0.15], [784, 0.2, 0.15], [1047, 0.4, 0.3]],                         // G5 G5 C6 — pedido na cozinha
7	  motoboy:    [[1047, 0, 0.15], [880, 0.2, 0.15], [1047, 0.4, 0.3]],                        // C6 A5 C6 — pronto p/ buscar
8	};
9	
10	export function useNotificacaoSonora(tipo = 'pedido') {
11	  const ctxRef = useRef(null);
12	
13	  const getCtx = () => {
14	    if (!ctxRef.current) {
15	      ctxRef.current = new (window.AudioContext || window.webkitAudioContext)();
16	    }
17	    return ctxRef.current;
18	  };
19	
20	  // Desbloqueia AudioContext no primeiro gesto do usuário
21	  useEffect(() => {
22	    const unlock = () => { try { getCtx().resume(); } catch {} };
23	    window.addEventListener('click', unlock, { once: true });
24	    window.addEventListener('touchstart', unlock, { once: true });
25	    return () => {
26	      window.removeEventListener('click', unlock);
27	      window.removeEventListener('touchstart', unlock);
28	    };
29	  }, []);
30	
31	  const tocar = useCallback(() => {
32	    try {
33	      const ctx = getCtx();
34	      const notas = TONES[tipo] ?? TONES.pedido;
35	      const play = () => {
36	        notas.forEach(([freq, start, dur]) => {
37	          const o = ctx.createOscillator();
38	          const g = ctx.createGain();
39	          o.connect(g); g.connect(ctx.destination);
40	          o.frequency.value = freq; o.type = 'square';
